CREATE TABLE IF NOT EXISTS migrations(version TEXT PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','staff','finance','viewer')),active INTEGER NOT NULL DEFAULT 1,epoch INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE tariffs(id TEXT PRIMARY KEY,name TEXT NOT NULL,brand TEXT NOT NULL CHECK(brand IN ('fitness','fighters')),monthly_cents INTEGER NOT NULL CHECK(monthly_cents>=0),enrollment_cents INTEGER NOT NULL CHECK(enrollment_cents>=0),max_discount INTEGER NOT NULL DEFAULT 0 CHECK(max_discount BETWEEN 0 AND 100),conditions TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE legal_versions(id TEXT PRIMARY KEY,brand TEXT NOT NULL,version TEXT NOT NULL,contract_text TEXT NOT NULL,privacy_text TEXT NOT NULL,bank_text TEXT NOT NULL,sepa_text TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0,approval_reference TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TRIGGER legal_texts_immutable BEFORE UPDATE OF contract_text,privacy_text,bank_text,sepa_text,version ON legal_versions BEGIN SELECT RAISE(ABORT,'immutable legal version'); END;
CREATE TABLE drafts(id TEXT PRIMARY KEY,session_hash TEXT NOT NULL,data_enc TEXT NOT NULL,review_enc TEXT,review_hash TEXT,discount_percent INTEGER NOT NULL DEFAULT 0,discount_reason TEXT,discount_actor TEXT,expires_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE members(id TEXT PRIMARY KEY,internal_reference TEXT NOT NULL UNIQUE,personal_enc TEXT NOT NULL,document_fingerprint TEXT NOT NULL UNIQUE,email_fingerprint TEXT,innux_reference TEXT UNIQUE,innux_number TEXT UNIQUE,innux_state TEXT NOT NULL DEFAULT 'PENDING_MANUAL',state TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL);
CREATE TABLE contracts(id TEXT PRIMARY KEY,reference TEXT NOT NULL UNIQUE,member_id TEXT NOT NULL REFERENCES members(id),tariff_id TEXT NOT NULL REFERENCES tariffs(id),snapshot_enc TEXT NOT NULL,snapshot_hash TEXT NOT NULL,pdf_enc TEXT NOT NULL,pdf_hash TEXT NOT NULL,signature_enc TEXT NOT NULL,evidence_enc TEXT NOT NULL,legal_id TEXT NOT NULL REFERENCES legal_versions(id),payment_method TEXT NOT NULL CHECK(payment_method IN ('cash','card','debit')),monthly_cents INTEGER NOT NULL,enrollment_cents INTEGER NOT NULL,initial_cents INTEGER NOT NULL,created_at TEXT NOT NULL,is_demo INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'SIGNED',center_accepted_at TEXT,center_actor TEXT,previous_id TEXT REFERENCES contracts(id));
CREATE TRIGGER signed_content_immutable BEFORE UPDATE OF snapshot_enc,snapshot_hash,pdf_enc,pdf_hash,signature_enc,evidence_enc,legal_id,payment_method,monthly_cents,enrollment_cents,initial_cents,tariff_id,member_id ON contracts BEGIN SELECT RAISE(ABORT,'immutable signed content'); END;
CREATE TRIGGER signed_no_delete BEFORE DELETE ON contracts BEGIN SELECT RAISE(ABORT,'signed contract: approved retention process required'); END;
CREATE TABLE mandates(id TEXT PRIMARY KEY,reference TEXT NOT NULL UNIQUE,member_id TEXT NOT NULL REFERENCES members(id),contract_id TEXT NOT NULL REFERENCES contracts(id),bank_enc TEXT NOT NULL,last_four TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('ACTIVE','PENDING_HOLDER','REVOKED')),holder_same INTEGER NOT NULL,signed_at TEXT,revoked_at TEXT,replaces_id TEXT REFERENCES mandates(id));
CREATE TABLE dues(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),contract_id TEXT NOT NULL REFERENCES contracts(id),mandate_id TEXT NOT NULL REFERENCES mandates(id),period TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),expected_cents INTEGER NOT NULL,adjustment_reason TEXT,adjustment_actor TEXT,concept TEXT NOT NULL,due_date TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'PREPARED' CHECK(state IN ('PREPARED','EXPORTED','SENT','CONFIRMED','RETURNED','CANCELLED')),revision INTEGER NOT NULL DEFAULT 1,UNIQUE(contract_id,period),UNIQUE(member_id,period));
CREATE TABLE export_profiles(id TEXT PRIMARY KEY,name TEXT NOT NULL,format TEXT NOT NULL CHECK(format IN ('csv','xlsx')),mapping_json TEXT NOT NULL,delimiter TEXT NOT NULL DEFAULT ';',decimal_separator TEXT NOT NULL DEFAULT ',',approved INTEGER NOT NULL DEFAULT 0,bank_reference TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE batches(id TEXT PRIMARY KEY,reference TEXT NOT NULL UNIQUE,period TEXT NOT NULL,profile_enc TEXT NOT NULL,file_enc TEXT NOT NULL,file_hash TEXT NOT NULL,filename TEXT NOT NULL,actor TEXT NOT NULL REFERENCES users(id),count INTEGER NOT NULL,total_cents INTEGER NOT NULL,created_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'EXPORTED');
CREATE TABLE batch_items(batch_id TEXT NOT NULL REFERENCES batches(id),due_id TEXT NOT NULL REFERENCES dues(id),amount_cents INTEGER NOT NULL,PRIMARY KEY(batch_id,due_id),UNIQUE(due_id));
CREATE TABLE previews(id TEXT PRIMARY KEY,actor TEXT NOT NULL,kind TEXT NOT NULL,payload_enc TEXT NOT NULL,payload_hash TEXT NOT NULL,expires_at TEXT NOT NULL,consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,detail_json TEXT NOT NULL,previous_hash TEXT NOT NULL,hash TEXT NOT NULL);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
CREATE TABLE settings(name TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE TABLE privacy_requests(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),reason TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'PENDING_REVIEW',actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE email_jobs(id TEXT PRIMARY KEY,contract_id TEXT NOT NULL REFERENCES contracts(id),state TEXT NOT NULL DEFAULT 'PROVIDER_REQUIRED',created_at TEXT NOT NULL);
CREATE TABLE mandate_evidence(id TEXT PRIMARY KEY,mandate_id TEXT NOT NULL UNIQUE REFERENCES mandates(id),snapshot_enc TEXT NOT NULL,signature_enc TEXT NOT NULL,pdf_enc TEXT NOT NULL,pdf_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER mandate_evidence_no_update BEFORE UPDATE ON mandate_evidence BEGIN SELECT RAISE(ABORT,'immutable mandate evidence'); END;
CREATE TRIGGER mandate_evidence_no_delete BEFORE DELETE ON mandate_evidence BEGIN SELECT RAISE(ABORT,'immutable mandate evidence'); END;
CREATE INDEX contracts_created ON contracts(created_at);
CREATE INDEX dues_period_state ON dues(period,state);
CREATE INDEX mandates_member ON mandates(member_id,state);
